import pandas as pd
import numpy as np


def _same_plan(a, b):
    a_null = pd.isna(a)
    b_null = pd.isna(b)
    if a_null and b_null:
        return True
    if a_null != b_null:
        return False
    return a == b


def run(inputs: dict) -> dict:
    dim = inputs["dim_account"].copy()
    stg = inputs["stg_account"].copy()

    # build per-account list of version dicts (mutable)
    versions = {}
    for acc_id, grp in dim.groupby("account_id"):
        vlist = []
        for _, row in grp.iterrows():
            vlist.append({
                "plan": row["plan"],
                "eff_start_date": row["eff_start_date"],
                "eff_end_date": row["eff_end_date"],
                "is_current": int(row["is_current"]),
            })
        versions[int(acc_id)] = vlist

    # sort staged records by account_id, update_date
    stg_sorted = stg.sort_values(["account_id", "update_date"], kind="mergesort")

    for _, s in stg_sorted.iterrows():
        acc_id = int(s["account_id"])
        s_plan = s["plan"]
        s_date = s["update_date"]

        if acc_id not in versions:
            versions[acc_id] = []

        vlist = versions[acc_id]

        if len(vlist) == 0:
            vlist.append({
                "plan": s_plan,
                "eff_start_date": s_date,
                "eff_end_date": pd.NaT,
                "is_current": 1,
            })
            continue

        # find covering version
        covering = None
        for v in vlist:
            start = v["eff_start_date"]
            end = v["eff_end_date"]
            if start <= s_date and (pd.isna(end) or s_date < end):
                covering = v
                break

        if covering is None:
            # earlier than earliest version
            f = min(vlist, key=lambda v: v["eff_start_date"])
            vlist.append({
                "plan": s_plan,
                "eff_start_date": s_date,
                "eff_end_date": f["eff_start_date"],
                "is_current": 0,
            })
        else:
            v = covering
            if _same_plan(v["plan"], s_plan):
                pass  # no-op
            elif s_date == v["eff_start_date"]:
                v["plan"] = s_plan
            else:
                vlist.append({
                    "plan": s_plan,
                    "eff_start_date": s_date,
                    "eff_end_date": v["eff_end_date"],
                    "is_current": v["is_current"],
                })
                v["eff_end_date"] = s_date
                v["is_current"] = 0

    # flatten
    rows = []
    for acc_id, vlist in versions.items():
        for v in vlist:
            rows.append({
                "account_id": acc_id,
                "plan": v["plan"],
                "eff_start_date": v["eff_start_date"],
                "eff_end_date": v["eff_end_date"],
                "is_current": v["is_current"],
            })

    out = pd.DataFrame(rows, columns=["account_id", "plan", "eff_start_date", "eff_end_date", "is_current"])

    if len(out) > 0:
        out["account_id"] = out["account_id"].astype("int64")
        out["eff_start_date"] = pd.to_datetime(out["eff_start_date"])
        out["eff_end_date"] = pd.to_datetime(out["eff_end_date"])
        out["is_current"] = out["is_current"].astype("int64")
        out = out.sort_values(["account_id", "eff_start_date"], kind="mergesort").reset_index(drop=True)

    return {"dim_account_out": out}
